using Microsoft.AspNetCore.Mvc;
using Nafadh_Backend.Services;
using static Nafadh_Backend.DTOs.ExcuseDto;

namespace Nafadh_Backend.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ExcuseController : ControllerBase
    {
        private readonly IExcuseService _service;
        private readonly IConfiguration _configuration;
        private readonly Nafadhcontext _context;

        public ExcuseController(
      IExcuseService service,
      IConfiguration configuration,
      Nafadhcontext context)
        {
            _service = service;
            _configuration = configuration;
            _context = context;
        }


        // =====================================================
        // GET EXCUSE BY ATTENDANCE
        // =====================================================

        // GET /api/Excuse/attendance/{dailyAttendanceId}
        [HttpGet("attendance/{dailyAttendanceId}")]
        public async Task<IActionResult> GetByAttendanceId(
            int dailyAttendanceId
        )
        {
            ExcuseReadDto? result =
                await _service.GetByDailyAttendanceIdAsync(
                    dailyAttendanceId
                );

            if (result == null)
            {
                return NotFound();
            }

            return Ok(result);
        }


        // =====================================================
        // CREATE EXCUSE WITH OPTIONAL PROOF FILE
        // =====================================================

        // POST /api/Excuse
        [HttpPost]
        [Consumes("multipart/form-data")]
       
        public async Task<IActionResult> Create(
            [FromForm] CreateExcuseFormDto form
        )
        {
            string? savedFilePath = null;

            try
            {
                if (
                    string.IsNullOrWhiteSpace(
                        form.Reason
                    )
                )
                {
                    return BadRequest(
                        new
                        {
                            message =
                                "Excuse reason is required."
                        }
                    );
                }


                // =================================================
                // OPTIONAL PROOF FILE
                // =================================================

                string? proofUrl = null;


                if (
                    form.File != null &&
                    form.File.Length > 0
                )
                {
                    var sizeSetting = await _context.SystemVariables
     .AsNoTracking()
     .FirstOrDefaultAsync(v =>
         v.VariableKey == "ATTACHMENT_MAX_SIZE_MB");

                    if (sizeSetting == null ||
                        !int.TryParse(sizeSetting.Value, out int maxSizeMb) ||
                        maxSizeMb <= 0)
                    {
                        return StatusCode(500, new
                        {
                            message = "Attachment size setting is invalid."
                        });
                    }

                    long maxFileSize = (long)maxSizeMb * 1024 * 1024;


                    if (
                        form.File.Length >
                        maxFileSize
                    )
                    {
                        return BadRequest(
                            new
                            {
                                message =
                                (await _context.SystemVariables
    .AsNoTracking()
    .Where(v => v.VariableKey == "ATTACHMENT_SIZE_ERROR")
    .Select(v => v.Value)
    .FirstOrDefaultAsync() ?? "Attachment exceeds the allowed size.")
    .Replace("{maxSize}", maxSizeMb.ToString())
                            }
                        );
                    }


                    var extension =
                        Path.GetExtension(
                            form.File.FileName
                        )
                        .ToLowerInvariant();


                    var extensionsSetting = await _context.SystemVariables
     .AsNoTracking()
     .FirstOrDefaultAsync(v =>
         v.VariableKey == "ATTACHMENT_ALLOWED_EXTENSIONS");

                    if (extensionsSetting == null ||
                        string.IsNullOrWhiteSpace(extensionsSetting.Value))
                    {
                        return StatusCode(500, new
                        {
                            message = "Allowed attachment extensions are not configured."
                        });
                    }

                    var allowedExtensions = extensionsSetting.Value
                        .Split(',', StringSplitOptions.RemoveEmptyEntries |
                                    StringSplitOptions.TrimEntries)
                        .Select(ext => "." + ext.TrimStart('.').ToLowerInvariant())
                        .ToHashSet(StringComparer.OrdinalIgnoreCase);


                    if (
                        !allowedExtensions.Contains(
                            extension
                        )
                    )
                    {
                        return BadRequest(
                            new
                            {
                                message =
                                    (await _context.SystemVariables
    .AsNoTracking()
    .Where(v => v.VariableKey == "ATTACHMENT_TYPE_ERROR")
    .Select(v => v.Value)
    .FirstOrDefaultAsync() ?? "Attachment file type is not allowed.")
                            }
                        );
                    }


                    var allowedContentTypes = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
{
    "application/pdf",
    "image/jpeg",
    "image/png",
    "application/msword",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "application/vnd.ms-excel",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
};

                    if (
                        !allowedContentTypes.Contains(
                            form.File.ContentType
                                .ToLowerInvariant()
                        )
                    )
                    {
                        return BadRequest(
                            new
                            {
                                message =
                                    "Invalid excuse attachment type."
                            }
                        );
                    }


                    // =================================================
                    // STORAGE
                    // =================================================

                    var storagePath =
                        _configuration[
                            "Storage:ExcuseProofsPath"
                        ];


                    if (
                        string.IsNullOrWhiteSpace(
                            storagePath
                        )
                    )
                    {
                        throw new InvalidOperationException(
                            "Excuse proof storage path is not configured."
                        );
                    }


                    Directory.CreateDirectory(
                        storagePath
                    );


                    var requestPath =
                        _configuration[
                            "Storage:ExcuseProofsRequestPath"
                        ]
                        ?? "/uploads/excuse-proofs";


                    requestPath =
                        requestPath.TrimEnd('/');


                    var fileName =
                        $"excuse-{form.DailyAttendanceId}-{Guid.NewGuid():N}{extension}";


                    savedFilePath =
                        Path.Combine(
                            storagePath,
                            fileName
                        );


                    await using (
                        var stream =
                            new FileStream(
                                savedFilePath,
                                FileMode.CreateNew
                            )
                    )
                    {
                        await form.File.CopyToAsync(
                            stream
                        );
                    }


                    proofUrl =
                        $"{requestPath}/{fileName}";
                }


                // =================================================
                // CREATE EXCUSE
                // =================================================

                var dto =
                    new CreateExcuseDto
                    {
                        DailyAttendanceId =
                            form.DailyAttendanceId,

                        Reason =
                            form.Reason.Trim(),

                        ProofUrl =
                            proofUrl
                    };


                ExcuseReadDto created =
                    await _service.CreateAsync(
                        dto
                    );


                return CreatedAtAction(
                    nameof(
                        GetByAttendanceId
                    ),
                    new
                    {
                        dailyAttendanceId =
                            created.DailyAttendanceId
                    },
                    created
                );
            }
            catch (
                InvalidOperationException ex
            )
            {
                // Delete the physical file if
                // creating the excuse failed.
                if (
                    !string.IsNullOrWhiteSpace(
                        savedFilePath
                    ) &&
                    System.IO.File.Exists(
                        savedFilePath
                    )
                )
                {
                    System.IO.File.Delete(
                        savedFilePath
                    );
                }


                return BadRequest(
                    new
                    {
                        message =
                            ex.Message
                    }
                );
            }
            catch (
                Exception ex
            )
            {
                if (
                    !string.IsNullOrWhiteSpace(
                        savedFilePath
                    ) &&
                    System.IO.File.Exists(
                        savedFilePath
                    )
                )
                {
                    System.IO.File.Delete(
                        savedFilePath
                    );
                }


                return StatusCode(
                    StatusCodes.Status500InternalServerError,
                    new
                    {
                        message =
                            "Could not create excuse.",
                        detail =
                            ex.Message
                    }
                );
            }
        }


        // =====================================================
        // REVIEW EXCUSE
        // =====================================================

        // PUT /api/Excuse/{id}/review
        [HttpPut("{id}/review")]
        public async Task<IActionResult> Review(
            int id,
            [FromBody] ReviewExcuseDto dto
        )
        {
            try
            {
                bool success =
                    await _service.ReviewAsync(
                        id,
                        dto
                    );


                if (!success)
                {
                    return NotFound();
                }


                return NoContent();
            }
            catch (
                InvalidOperationException ex
            )
            {
                return BadRequest(
                    ex.Message
                );
            }
        }


